1→import { DatabaseSync } from "node:sqlite";
import { dirname } from "node:path";
import { mkdirSync } from "node:fs";

export type Database = DatabaseSync;

export function openDatabase(path: string): Database {
  if (path !== ":memory:") mkdirSync(dirname(path), { recursive: true });
  const db = new DatabaseSync(path);
10→  db.exec("PRAGMA journal_mode = WAL");
  db.exec("PRAGMA synchronous = FULL");
  db.exec("PRAGMA foreign_keys = ON");
  db.exec("PRAGMA busy_timeout = 5000");
  migrate(db);
  return db;
}

function migrate(db: Database): void {
  db.exec(`
20→    BEGIN IMMEDIATE;
    CREATE TABLE IF NOT EXISTS accounts (
      account_id TEXT PRIMARY KEY,
      email TEXT NOT NULL UNIQUE,
      password_hash TEXT NOT NULL,
      status TEXT NOT NULL CHECK (status = 'ACTIVE'),
      created_at TEXT NOT NULL,
      eth_available TEXT NOT NULL DEFAULT '0' CHECK (eth_available = '0'),
      eth_locked TEXT NOT NULL DEFAULT '0' CHECK (eth_locked = '0'),
      usdc_available TEXT NOT NULL DEFAULT '0' CHECK (usdc_available = '0'),
30→      usdc_locked TEXT NOT NULL DEFAULT '0' CHECK (usdc_locked = '0')
    ) STRICT;
    CREATE TABLE IF NOT EXISTS sessions (
      token_hash TEXT PRIMARY KEY,
      account_id TEXT NOT NULL REFERENCES accounts(account_id),
      expires_at TEXT NOT NULL
    ) STRICT;
    CREATE INDEX IF NOT EXISTS sessions_account_idx ON sessions(account_id);
    CREATE TABLE IF NOT EXISTS auth_audit (
      id INTEGER PRIMARY KEY,
40→      timestamp TEXT NOT NULL,
      email TEXT NOT NULL,
      result TEXT NOT NULL CHECK (result IN ('SUCCESS', 'FAILURE')),
      reason TEXT,
      origin TEXT NOT NULL
    ) STRICT;
    CREATE TABLE IF NOT EXISTS wallet_secret (
      singleton_id INTEGER PRIMARY KEY CHECK (singleton_id = 1),
      encrypted_seed BLOB NOT NULL,
      created_at TEXT NOT NULL
50→    ) STRICT;
    CREATE TABLE IF NOT EXISTS deposit_addresses (
      account_id TEXT PRIMARY KEY REFERENCES accounts(account_id),
      address_index INTEGER NOT NULL UNIQUE CHECK (address_index >= 0 AND address_index <= 2147483647),
      address TEXT NOT NULL UNIQUE,
      derivation_path TEXT NOT NULL,
      network TEXT NOT NULL CHECK (network = 'sepolia'),
      chain_id TEXT NOT NULL CHECK (chain_id = '11155111')
    ) STRICT;
    CREATE TABLE IF NOT EXISTS domain_events (
60→      id INTEGER PRIMARY KEY,
      type TEXT NOT NULL,
      payload TEXT NOT NULL,
      created_at TEXT NOT NULL
    ) STRICT;
    COMMIT;
  `);
}

export function immediateTransaction<T>(db: Database, work: () => T): T {
70→  db.exec("BEGIN IMMEDIATE");
  try {
    const result = work();
    db.exec("COMMIT");
    return result;
  } catch (error) {
    db.exec("ROLLBACK");
    throw error;
  }
}
