1→import {
  createCipheriv,
  createDecipheriv,
  createHmac,
  pbkdf2Sync,
  randomBytes,
  timingSafeEqual,
} from "node:crypto";

10→import {
  getAddress,
  keccak256,
  Mnemonic,
  SigningKey,
  wordlists,
} from "ethers";

export const HARDENED_OFFSET = 0x80000000;
export const MAX_ADDRESS_INDEX = HARDENED_OFFSET - 1;
20→export const WALLET_SEED_BYTES = 64;
export const AES_256_KEY_BYTES = 32;
export const AES_GCM_NONCE_BYTES = 12;
export const AES_GCM_TAG_BYTES = 16;

export interface ValidationIssue {
  field: string;
  message: string;
}

30→export class WalletCryptoError extends Error {
  readonly code: "VALIDATION_ERROR" | "INTERNAL_ERROR";
  readonly issues?: readonly ValidationIssue[];

  constructor(
    code: "VALIDATION_ERROR" | "INTERNAL_ERROR",
    message: string,
    issues?: readonly ValidationIssue[],
  ) {
    super(message);
40→    this.name = "WalletCryptoError";
    this.code = code;
    this.issues = issues;
  }
}

export interface DerivedEthereumKey {
  addressIndex: number;
  derivationPath: string;
  /** Compressed secp256k1 public key. Private material is deliberately omitted. */
50→  publicKey: string;
  address: string;
}

type RandomBytesSource = (length: number) => Uint8Array;
export type HmacSha512 = (key: Uint8Array, data: Uint8Array) => Uint8Array;

const SECP256K1_ORDER = BigInt("0xFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFEBAAEDCE6AF48A03BBFD25E8CD0364141");
const BIP32_MASTER_KEY = Buffer.from("Bitcoin seed", "ascii");
const MAX_BIP32_INDEX = 0xffffffff;
60→
function validationError(field: string, message: string): WalletCryptoError {
  return new WalletCryptoError("VALIDATION_ERROR", message, [{ field, message }]);
}

function asBuffer(bytes: Uint8Array): Buffer {
  return Buffer.from(bytes.buffer, bytes.byteOffset, bytes.byteLength);
}

/** BIP-39 requires NFKD normalization for both the phrase and passphrase. */
70→export function normalizeNfkd(value: string): string {
  return value.normalize("NFKD");
}

/**
 * Derive the 512-bit BIP-39 seed. This intentionally accepts any BIP-39 phrase
 * length so canonical 12-word algorithm vectors can be exercised. Production
 * provisioning must call validateProvisioningMnemonic separately.
 */
export function deriveBip39Seed(
80→  mnemonic: string,
  passphrase = "",
): Uint8Array {
  const normalizedMnemonic = normalizeNfkd(mnemonic);
  const salt = `mnemonic${normalizeNfkd(passphrase)}`;
  return new Uint8Array(
    pbkdf2Sync(normalizedMnemonic, salt, 2048, WALLET_SEED_BYTES, "sha512"),
  );
}

90→/**
 * Validate and canonicalize the only mnemonic form accepted for provisioning:
 * 256 bits of entropy encoded as 24 words from the English BIP-39 wordlist.
 */
export function validateProvisioningMnemonic(mnemonic: string): string {
  const words = normalizeNfkd(mnemonic).trim().split(/\s+/u);

  // The prescribed order is length, wordlist membership, then checksum.
  if (words.length !== 24) {
    throw validationError("mnemonic", "El mnemonic debe contener exactamente 24 palabras.");
100→  }

  for (const word of words) {
    if (wordlists.en.getWordIndex(word) < 0) {
      throw validationError("mnemonic", "El mnemonic contiene una palabra fuera del wordlist BIP-39 inglés.");
    }
  }

  const canonicalMnemonic = words.join(" ");
  if (!Mnemonic.isValidMnemonic(canonicalMnemonic, wordlists.en)) {
110→    throw validationError("mnemonic", "El checksum BIP-39 del mnemonic es inválido.");
  }

  return canonicalMnemonic;
}

/** Generate a fresh 24-word English BIP-39 mnemonic from 256 CSPRNG bits. */
export function generateProvisioningMnemonic(
  randomSource: RandomBytesSource = randomBytes,
): string {
120→  const entropy = randomSource(32);
  if (entropy.byteLength !== 32) {
    throw new WalletCryptoError(
      "INTERNAL_ERROR",
      "El CSPRNG no produjo los 256 bits de entropía requeridos.",
    );
  }
  return Mnemonic.entropyToPhrase(entropy, wordlists.en);
}

130→function validateEncryptionKey(key: Uint8Array): void {
  if (key.byteLength !== AES_256_KEY_BYTES) {
    throw new WalletCryptoError(
      "INTERNAL_ERROR",
      "La credencial de cifrado AES-256-GCM es inválida.",
    );
  }
}

/**
140→ * Encrypt a 64-byte BIP-39 seed as nonce || ciphertext || authentication tag.
 * A new 96-bit CSPRNG nonce is requested for every invocation.
 */
export function encryptSeed(
  seed: Uint8Array,
  key: Uint8Array,
  randomSource: RandomBytesSource = randomBytes,
): Uint8Array {
  validateEncryptionKey(key);
  if (seed.byteLength !== WALLET_SEED_BYTES) {
150→    throw new WalletCryptoError("INTERNAL_ERROR", "La seed debe contener exactamente 64 bytes.");
  }

  const nonce = randomSource(AES_GCM_NONCE_BYTES);
  if (nonce.byteLength !== AES_GCM_NONCE_BYTES) {
    throw new WalletCryptoError("INTERNAL_ERROR", "El nonce AES-GCM debe contener exactamente 12 bytes.");
  }

  const cipher = createCipheriv("aes-256-gcm", asBuffer(key), asBuffer(nonce), {
    authTagLength: AES_GCM_TAG_BYTES,
160→  });
  const ciphertext = Buffer.concat([cipher.update(asBuffer(seed)), cipher.final()]);
  const tag = cipher.getAuthTag();

  return new Uint8Array(Buffer.concat([asBuffer(nonce), ciphertext, tag]));
}

/** Authenticate and decrypt a nonce || ciphertext || tag seed envelope. */
export function decryptSeed(envelope: Uint8Array, key: Uint8Array): Uint8Array {
  validateEncryptionKey(key);
170→  const expectedLength = AES_GCM_NONCE_BYTES + WALLET_SEED_BYTES + AES_GCM_TAG_BYTES;
  if (envelope.byteLength !== expectedLength) {
    throw new WalletCryptoError("INTERNAL_ERROR", "El material cifrado de la wallet es inválido.");
  }

  const payload = asBuffer(envelope);
  const nonce = payload.subarray(0, AES_GCM_NONCE_BYTES);
  const tag = payload.subarray(payload.length - AES_GCM_TAG_BYTES);
  const ciphertext = payload.subarray(AES_GCM_NONCE_BYTES, payload.length - AES_GCM_TAG_BYTES);

180→  try {
    const decipher = createDecipheriv("aes-256-gcm", asBuffer(key), nonce, {
      authTagLength: AES_GCM_TAG_BYTES,
    });
    decipher.setAuthTag(tag);
    const seed = Buffer.concat([decipher.update(ciphertext), decipher.final()]);
    if (seed.byteLength !== WALLET_SEED_BYTES) {
      throw new Error("invalid plaintext length");
    }
    return new Uint8Array(seed);
190→  } catch {
    // Keep authentication failures deliberately opaque; never include secret data.
    throw new WalletCryptoError(
      "INTERNAL_ERROR",
      "No se pudo autenticar ni descifrar el seed de la wallet.",
    );
  }
}

export function validateAddressIndex(addressIndex: number): number {
200→  if (!Number.isInteger(addressIndex) || addressIndex < 0 || addressIndex > MAX_ADDRESS_INDEX) {
    throw validationError(
      "address_index",
      `address_index debe ser un entero entre 0 y ${MAX_ADDRESS_INDEX}.`,
    );
  }
  return addressIndex;
}

export function ethereumDerivationPath(addressIndex: number): string {
210→  validateAddressIndex(addressIndex);
  return `m/44'/60'/0'/0/${addressIndex}`;
}

/** Derive only non-secret Ethereum account material from a BIP-39 seed. */
export function deriveEthereumKey(
  seed: Uint8Array,
  addressIndex: number,
  hmacSha512: HmacSha512 = defaultHmacSha512,
): DerivedEthereumKey {
220→  if (seed.byteLength !== WALLET_SEED_BYTES) {
    throw new WalletCryptoError("INTERNAL_ERROR", "La seed debe contener exactamente 64 bytes.");
  }

  validateAddressIndex(addressIndex);
  const master = hmacSha512(BIP32_MASTER_KEY, seed);
  if (master.byteLength !== 64) {
    throw new WalletCryptoError("INTERNAL_ERROR", "La derivación BIP-32 produjo una salida inválida.");
  }
  const masterPrivateKey = bytesToBigInt(master.subarray(0, 32));
230→  if (masterPrivateKey < 1n || masterPrivateKey >= SECP256K1_ORDER) {
    throw new WalletCryptoError("INTERNAL_ERROR", "La clave maestra BIP-32 es inválida.");
  }
  const masterChainCode = master.subarray(32, 64);

  const requestedPath = [
    44 + HARDENED_OFFSET,
    60 + HARDENED_OFFSET,
    HARDENED_OFFSET,
    0,
240→    addressIndex,
  ];
  const effectivePath: number[] = [];
  let node: ExtendedPrivateKey = {
    privateKey: masterPrivateKey,
    chainCode: masterChainCode,
  };

  for (const [level, requestedIndex] of requestedPath.entries()) {
    // BIP-32 says that an invalid child advances i in the CKDpriv invocation that
250→    // failed. Hardened components may therefore advance through the hardened range;
    // change and address_index remain in BIP-44's non-hardened range.
    const maximumIndex = level < 3 ? MAX_BIP32_INDEX : MAX_ADDRESS_INDEX;
    const derived = deriveValidChild(node, requestedIndex, maximumIndex, hmacSha512);
    node = derived.child;
    effectivePath.push(derived.effectiveIndex);
  }

  const effectiveAddressIndex = effectivePath[4]!;
  const privateHex = `0x${bigIntTo32Bytes(node.privateKey).toString("hex")}`;
260→  const publicKey = SigningKey.computePublicKey(privateHex, true);
  const uncompressed = SigningKey.computePublicKey(privateHex, false);
  const rawAddress = keccak256(`0x${uncompressed.slice(4)}`).slice(-40);
  return {
    addressIndex: effectiveAddressIndex,
    derivationPath: formatEffectiveDerivationPath(effectivePath),
    publicKey,
    address: getAddress(`0x${rawAddress}`),
  };
}
270→
export function deriveEthereumAddress(seed: Uint8Array, addressIndex: number): string {
  return deriveEthereumKey(seed, addressIndex).address;
}

function defaultHmacSha512(key: Uint8Array, data: Uint8Array): Uint8Array {
  return createHmac("sha512", asBuffer(key)).update(asBuffer(data)).digest();
}

interface ExtendedPrivateKey {
280→  privateKey: bigint;
  chainCode: Uint8Array;
}

function deriveValidChild(
  parent: ExtendedPrivateKey,
  requestedIndex: number,
  maximumIndex: number,
  hmacSha512: HmacSha512,
): { child: ExtendedPrivateKey; effectiveIndex: number } {
290→  for (let index = requestedIndex; index <= maximumIndex; index += 1) {
    const privateBytes = bigIntTo32Bytes(parent.privateKey);
    const data = index >= HARDENED_OFFSET
      ? Buffer.concat([Buffer.from([0]), privateBytes, ser32(index)])
      : Buffer.concat([
          Buffer.from(SigningKey.computePublicKey(`0x${privateBytes.toString("hex")}`, true).slice(2), "hex"),
          ser32(index),
        ]);
    const output = hmacSha512(parent.chainCode, data);
    if (output.byteLength !== 64) {
300→      throw new WalletCryptoError("INTERNAL_ERROR", "La derivación BIP-32 produjo una salida inválida.");
    }
    const left = bytesToBigInt(output.subarray(0, 32));
    if (left >= SECP256K1_ORDER) continue;
    const childPrivateKey = (left + parent.privateKey) % SECP256K1_ORDER;
    if (childPrivateKey === 0n) continue;
    return {
      child: {
        privateKey: childPrivateKey,
        chainCode: output.subarray(32, 64),
310→      },
      effectiveIndex: index,
    };
  }
  throw new WalletCryptoError("INTERNAL_ERROR", "Se agotó el rango BIP-32 del nivel de derivación.");
}

function formatEffectiveDerivationPath(path: readonly number[]): string {
  const [purpose, coinType, account, change, addressIndex] = path;
  return `m/${purpose! - HARDENED_OFFSET}'/${coinType! - HARDENED_OFFSET}'/${account! - HARDENED_OFFSET}'/${change}/${addressIndex}`;
320→}

function ser32(value: number): Buffer {
  const result = Buffer.allocUnsafe(4);
  result.writeUInt32BE(value, 0);
  return result;
}

function bytesToBigInt(value: Uint8Array): bigint {
  return BigInt(`0x${Buffer.from(value).toString("hex")}`);
330→}

function bigIntTo32Bytes(value: bigint): Buffer {
  return Buffer.from(value.toString(16).padStart(64, "0"), "hex");
}

/** Apply or validate the mixed-case EIP-55 checksum for a raw 20-byte address. */
export function toChecksumAddress(rawAddress: string): string {
  const body = rawAddress.startsWith("0x") ? rawAddress.slice(2) : rawAddress;
  if (!/^[0-9a-fA-F]{40}$/.test(body)) {
340→    throw validationError("address", "La dirección Ethereum debe contener exactamente 20 bytes hexadecimales.");
  }
  try {
    return getAddress(`0x${body}`);
  } catch {
    throw validationError("address", "El checksum EIP-55 de la dirección es inválido.");
  }
}

/** Constant-time equality helper suitable for startup seed-integrity checks. */
350→export function secretBytesEqual(left: Uint8Array, right: Uint8Array): boolean {
  if (left.byteLength !== right.byteLength) return false;
  return timingSafeEqual(asBuffer(left), asBuffer(right));
}

1→import { getAddress } from "ethers";
import { resolve } from "node:path";

export const CHAIN_ID = "11155111";

export interface Config {
  host: string;
  port: number;
  databasePath: string;
10→  sessionTtlSeconds: number;
  walletEncryptionKey: Buffer;
  usdcTokenAddress: string;
  rpcUrl: string;
  walletMnemonic?: string;
  walletPassphrase: string;
}

function required(env: NodeJS.ProcessEnv, name: string): string {
  const value = env[name]?.trim();
20→  if (!value) throw new Error(`Configuración inválida: falta ${name}`);
  return value;
}

function encryptionKey(raw: string): Buffer {
  let key: Buffer;
  if (/^[0-9a-fA-F]{64}$/.test(raw)) key = Buffer.from(raw, "hex");
  else key = Buffer.from(raw, "base64");
  if (key.length !== 32) {
    throw new Error("Configuración inválida: WALLET_ENCRYPTION_KEY debe contener 32 bytes");
30→  }
  return key;
}

export function loadConfig(env: NodeJS.ProcessEnv = process.env): Config {
  const ttlRaw = env.SESSION_TTL_SECONDS ?? "3600";
  if (!/^[0-9]+$/.test(ttlRaw)) {
    throw new Error("Configuración inválida: SESSION_TTL_SECONDS debe ser entero");
  }
  const sessionTtlSeconds = Number(ttlRaw);
40→  if (sessionTtlSeconds < 60 || sessionTtlSeconds > 86_400) {
    throw new Error("Configuración inválida: SESSION_TTL_SECONDS debe estar entre 60 y 86400");
  }

  const portRaw = env.PORT ?? "3000";
  if (!/^[0-9]+$/.test(portRaw) || Number(portRaw) < 1 || Number(portRaw) > 65_535) {
    throw new Error("Configuración inválida: PORT debe estar entre 1 y 65535");
  }

  const addressRaw = required(env, "USDC_TOKEN_ADDRESS");
